let assess;
let models;
async function init(){if(!models)models=(async()=>{const {FilesetResolver,FaceLandmarker,ImageSegmenter}=await import('./vendor/vision_bundle.mjs');({assess}=await import('./analysis.mjs?v=2'));const vision=await FilesetResolver.forVisionTasks(new URL('./vendor/wasm',self.location.href).href);const face=await FaceLandmarker.createFromOptions(vision,{baseOptions:{modelAssetPath:new URL('./models/face_landmarker.task',self.location.href).href,delegate:'CPU'},runningMode:'IMAGE',numFaces:3,outputFaceBlendshapes:true,outputFacialTransformationMatrixes:true});const segment=await ImageSegmenter.createFromOptions(vision,{baseOptions:{modelAssetPath:new URL('./models/selfie_multiclass.tflite',self.location.href).href,delegate:'CPU'},runningMode:'IMAGE',outputCategoryMask:true,outputConfidenceMasks:false});return {face,segment}})();return models;}
self.onmessage=async({data})=>{const {id,bitmap,sourceWidth,sourceHeight,upscaled}=data;try{const {face,segment}=await init();const canvas=new OffscreenCanvas(bitmap.width,bitmap.height),ctx=canvas.getContext('2d',{willReadFrequently:true});ctx.drawImage(bitmap,0,0);const faceResult=face.detect(canvas);let result=segment.segment(canvas);try{const rows=assess({width:canvas.width,height:canvas.height,pixels:ctx.getImageData(0,0,canvas.width,canvas.height).data,faceResult,mask:result.categoryMask.getAsUint8Array(),maskWidth:result.categoryMask.width,maskHeight:result.categoryMask.height,sourceWidth,sourceHeight,upscaled});self.postMessage({id,rows});}finally{result.close();}}catch(error){models=null;self.postMessage({id,error:'Automatic analysis could not run. Your browser may not support the required on-device models, or model files could not load. You can retry or download the crop without verification.'});console.error(error);}finally{bitmap.close();}};
